import{_ as r,a as t,c as o,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-4/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","link":"/life/english/new-concept/book-4/grammar-part-04"},"next":{"text":"第四册：流利英语 · 全册单词总结","link":"/life/english/new-concept/book-4/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","link":"/life/english/new-concept/book-4/grammar-part-04"},"next":{"text":"第四册：流利英语 · 全册单词总结","link":"/life/english/new-concept/book-4/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/grammar-part-05.md","filePath":"life/english/new-concept/book-4/grammar-part-05.md"}'),n={name:"life/english/new-concept/book-4/grammar-part-05.md"};function i(h,e,s,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-全册语法总结-·-there-be-与存在命题至决策段落中的-however、therefore-与条件" tabindex="-1">第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件 <a class="header-anchor" href="#第四册-流利英语-·-全册语法总结-·-there-be-与存在命题至决策段落中的-however、therefore-与条件" aria-label="Permalink to &quot;第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="there-be-与存在命题" tabindex="-1">there be 与存在命题 <a class="header-anchor" href="#there-be-与存在命题" aria-label="Permalink to &quot;there be 与存在命题 {#there-be-与存在命题}&quot;">​</a></h2><p>there be 用来引入某处或某情境中存在的事物，there 不表示实际地点；谓语通常与后面的名词一致。There may be an alternative explanation. 表示可能存在解释，不保证解释为真。there is no evidence that… 意为没有支持该命题的证据，不自动等于该命题已被证明为假。避免 there have 代替 there be；若强调某人拥有物品，改用 have 的普通主谓结构。</p><p><strong>L43 原创例句：</strong> There may be a simpler explanation for the unusual signal.</p><p>这个异常信号可能有一种更简单的解释。</p><p><strong>易错：</strong> There have a signal 不成立；应写 There is a signal 或 The receiver has detected a signal。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-043">Lesson 43</a></p><h2 id="限制性与非限制性从句的范围差异" tabindex="-1">限制性与非限制性从句的范围差异 <a class="header-anchor" href="#限制性与非限制性从句的范围差异" aria-label="Permalink to &quot;限制性与非限制性从句的范围差异 {#限制性与非限制性从句的范围差异}&quot;">​</a></h2><p>The participants who arrived early helped us. 只说早到的那部分参与者；The participants, who arrived early, helped us. 把早到作为这组参与者共同的补充信息。逗号改变所指范围，不只是朗读停顿。非限制性从句通常不用 that，也不能省关系代词。文化描述尤其要先限定群体，再加补充说明；否则容易把少数人的观察扩展成整个文化的属性。</p><p><strong>L44 原创例句：</strong> The visitors who had attended the workshop recognised the greeting.</p><p>参加过工作坊的那些访客认出了这种问候方式。</p><p><strong>易错：</strong> 给 who 从句随意加逗号会改变范围：有逗号时通常将参加工作坊作为整组访客的补充信息。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-044">Lesson 44</a></p><h2 id="no-more-than-与-not-more-than" tabindex="-1">no more than 与 not more than <a class="header-anchor" href="#no-more-than-与-not-more-than" aria-label="Permalink to &quot;no more than 与 not more than {#no-more-than-与-not-more-than}&quot;">​</a></h2><p>more than 表超过；not more than 表不超过，是数量上限；no more than 常表示“仅仅”，带有数量少的评价，也可在明确数量语境中表达上限。no less than 常带“竟有”或“不少于”的强调，需看语境。阅读有关科学影响的数量论证时，先把数学边界写出来，再判断修辞语气；少量信息可能带来重大影响是论点，不能仅靠数字修辞代替证据。</p><p><strong>L45 原创例句：</strong> The summary contained no more than three pages, yet it raised questions the committee had overlooked.</p><p>摘要仅有三页，却提出了委员会此前忽略的问题。</p><p><strong>易错：</strong> not more than 10 表 ≤10，不是 &lt;10；上限本身也在允许范围内。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-045">Lesson 45</a></p><h2 id="would-rather-与-prefer-的补语" tabindex="-1">would rather 与 prefer 的补语 <a class="header-anchor" href="#would-rather-与-prefer-的补语" aria-label="Permalink to &quot;would rather 与 prefer 的补语 {#would-rather-与-prefer-的补语}&quot;">​</a></h2><p>would rather + 动词原形表示宁愿做某事；would rather A than B 中两个动词保持原形。prefer doing A to doing B 使用介词 to，不是比较连词 than。prefer to do A rather than do B 也是常见形式。would rather 后若另有主语，常用过去式表达现在或未来偏好，如 I would rather you came tomorrow；这不是叙述过去已经来过。</p><p><strong>L46 原创例句：</strong> I would rather repair an old radio than buy another one.</p><p>我宁愿修理一台旧收音机，也不愿再买一台。</p><p><strong>易错：</strong> prefer repairing than buying 错把两套搭配混合；应写 prefer repairing to buying。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-046">Lesson 46</a></p><h2 id="篇章指代与-this-概括名词" tabindex="-1">篇章指代与 this + 概括名词 <a class="header-anchor" href="#篇章指代与-this-概括名词" aria-label="Permalink to &quot;篇章指代与 this + 概括名词 {#篇章指代与-this-概括名词}&quot;">​</a></h2><p>this/that 可以指前一句或前一段的整体意思，但裸用 This is important 常让读者不知指代对象。使用 this expectation、that assumption、such a contrast 等概括名词，可把关系说清楚。概括名词本身也包含解释，不能随意把前句的“可能”称为 this fact。指代不应跨越太多竞争对象；若有两个可指对象，重复关键名词往往比继续用代词更清晰。</p><p><strong>L47 原创例句：</strong> We expected the trip to remove every worry. That expectation proved unrealistic.</p><p>我们原以为旅行能消除所有烦恼。事实证明，这一期待不切实际。</p><p><strong>易错：</strong> 前句只是猜测时，后句不能随意称 this fact；应使用 this possibility 或 this assumption。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-047">Lesson 47</a></p><h2 id="决策段落中的-however、therefore-与条件" tabindex="-1">决策段落中的 however、therefore 与条件 <a class="header-anchor" href="#决策段落中的-however、therefore-与条件" aria-label="Permalink to &quot;决策段落中的 however、therefore 与条件 {#决策段落中的-however、therefore-与条件}&quot;">​</a></h2><p>however 引入转折，therefore 引出推论，for example 提供实例；它们通常是连接副词，不能只用一个逗号拼接两个独立句。可写 The options differ; therefore, we need a clear criterion，或分成两句。if 从句为结论设条件，provided that 表在某前提成立时。连接词应反映真实逻辑关系；没有支持理由时加 therefore 不会让结论自动有效。</p><p><strong>L48 原创例句：</strong> The two plans serve different objectives; therefore, comparing returns alone would be misleading.</p><p>这两种方案服务于不同目标；因此，只比较回报会产生误导。</p><p><strong>易错：</strong> The plans differ, however they… 是逗号拼接；应在 however 前用句号或分号，并根据结构加逗号。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-048">Lesson 48</a></p>',39)])])}const f=r(n,[["render",i]]);export{d as __pageData,f as default};
